/**
 * Session-level reader-journey analytics for the admin dashboard: recirculation, session depth, entry articles, top reading paths, recommendation-click breakdown, and swipe-prompt conversion. Filtered by an optional [from, to) UTC date-time window. No PII.

 * @summary Aggregated anonymous reader-journey metrics
 */
export const getGetReaderJourneyReportUrl = (
  params?: GetReaderJourneyReportParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/reader-journeys?${stringifiedParams}`
    : `/api/admin/reader-journeys`;
};

