/**
 * @summary Project each active author's upcoming publish slots, filled with their next-up draft or approved idea
 */
export const getGetScheduleProjectionUrl = (
  params?: GetScheduleProjectionParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/schedule/projection?${stringifiedParams}`
    : `/api/admin/schedule/projection`;
};

export const getScheduleProjection = async (
  params?: GetScheduleProjectionParams,
  options?: RequestInit,
): Promise<GetScheduleProjection200> => {
  return customFetch<GetScheduleProjection200>(
    getGetScheduleProjectionUrl(params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetScheduleProjectionQueryKey = (
  params?: GetScheduleProjectionParams,
) => {
  return [
    `/api/admin/schedule/projection`,
    ...(params ? [params] : []),
  ] as const;
};

