/**
 * @summary List drafts and approved ideas for an author, used to populate the swap dialog
 */
export const getListSwappableUrl = (params: ListSwappableParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/schedule/swappable?${stringifiedParams}`
    : `/api/admin/schedule/swappable`;
};

