/**
 * Returns all clusters with watched=true. Each cluster includes a `newDocsSinceViewed` count (documents added since the editor last called mark-viewed). Call mark-viewed after rendering to reset the badge.

 * @summary List watched story clusters ordered by last-signal date (most recent first)
 */
export const getListWatchedClustersUrl = (
  params?: ListWatchedClustersParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/trends/clusters/watched?${stringifiedParams}`
    : `/api/admin/trends/clusters/watched`;
};

